def call0(obj, name):
    r = getattr(obj, name)
    if isinstance(r, win32com.client.CDispatch) or not callable(r):
        return r
    return r()


def sw_constant(app, enum, member):
    import os
    exe = app.GetExecutablePath
    exe = str(exe() if callable(exe) else exe)
    for f in (exe, os.path.dirname(exe)):
        for sub in ((), ("api",)):
            path = os.path.join(f, *sub, "swconst.tlb")
            if not os.path.exists(path):
                continue
            tl = pythoncom.LoadTypeLib(path)
            for i in range(tl.GetTypeInfoCount()):
                if tl.GetDocumentation(i)[0] != enum:
                    continue
                ti = tl.GetTypeInfo(i)
                for j in range(ti.GetTypeAttr().cVars):
                    vd = ti.GetVarDesc(j)
                    if ti.GetNames(vd.memid)[0] == member:
                        return int(vd.value)
    raise LookupError(f"{enum}.{member} not found")


app = win32com.client.Dispatch("SldWorks.Application")
app.Visible = True
try:
    app.SetUserPreferenceToggle(10, False)
except Exception:
    pass
CONST = {}
for enum, member, default in (("swFeatureNameID_e", "swFmSweep", 17), ("swFeatureNameID_e", "swFmFillet", 1),
                              ("swSimpleFilletType_e", "swConstRadiusFillet", 0),
                              ("swEndConditions_e", "swEndCondMidPlane", 6)):
    try:
        CONST[member] = sw_constant(app, enum, member)
    except Exception:
        CONST[member] = default


def new_part():
    m = call0(app, "NewPart")
    try:
        m.Extension.SetUserPreferenceInteger(sw_constant(app, "swUserPreferenceIntegerValue_e", "swUnitSystem"),
                                             0, sw_constant(app, "swUnitSystem_e", "swUnitSystem_MMGS"))
    except Exception:
        pass
    return m


def mass(m):
    m.ForceRebuild3(False)
    mp = call0(m.Extension, "CreateMassProperty")
    if mp is None:
        return 0.0, (0.0, 0.0, 0.0)
    return mp.Volume / MM ** 3, tuple(c / MM for c in mp.CenterOfMass)


STATE = dict(drift=0.0)


def check(m, step, f, quiet=False, tol=None):
    """Volume and centre after a feature against STEPS[step]. The feature's own change is compared: the
    differences of the features before it (SolidWorks' and CadQuery's lofts differ by a few mm^3) are carried."""
    ev, ec, own = STEPS[step]
    if f is None:
        if own <= 1.0 and step.endswith("cut"):
            print(f"{step}: nothing to cut (SolidWorks makes no feature) -> OK")
            return True
        if not quiet:
            print(f"{step}: NOT MADE")
            STATE["drift"] -= own               # the part lacks this feature's change from here on
        return False
    v, c = mass(m)
    d = v - ev - STATE["drift"]
    ok = abs(d) <= (TOL if tol is None else tol) * abs(own) + ABS_TOL
    if not quiet or ok:
        print(f"{step}: volume {v:.3f} mm^3 (expected {ev:.3f}; own change off by {d:+.3f}, carried {STATE['drift']:+.3f});"
              f" centre {math.dist(c, ec):.4f} mm off -> {'OK' if ok else 'DIFFERS'}")
    if ok or not quiet:                         # a feature that stays in the part: its difference is carried
        STATE["drift"] = v - ev
    return ok


def to_sk(T, p):
    x = [c * MM for c in p]
    return tuple((sum(x[i] * T[3 * i + j] for i in range(3)) + T[9 + j]) * T[12] for j in range(3))


def open_sketch(m, plane):
    sm = m.SketchManager
    for attempt in range(3):
        m.ClearSelection2(True)
        if isinstance(plane, str):
            m.Extension.SelectByID2(plane, "PLANE", 0, 0, 0, False, 0, NOTHING, 0)
        else:
            plane.Select2(False, 0)
        sm.InsertSketch(True)
        sk = call0(sm, "ActiveSketch")
        if sk is not None:
            break
    else:
        raise RuntimeError("no sketch opened")
    T = list(sk.ModelToSketchTransform.ArrayData)
    sm.AddToDB = True
    helper = sm.CreateCircleByRadius(-0.5, -0.5, 0.0, 0.5 * MM)
    return sm, T, helper


def close_sketch(m, sm, helper, name):
    sm.AddToDB = False
    m.ClearSelection2(True)
    helper.Select4(False, NOTHING)
    m.EditDelete()
    sm.InsertSketch(True)
    f = m.FeatureByPositionReverse(0)
    f.Name = name
    return f


def circle_centre(p, q, r):
    ax, ay = p; bx, by = q; cx, cy = r
    d = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))
    ux = ((ax * ax + ay * ay) * (by - cy) + (bx * bx + by * by) * (cy - ay) + (cx * cx + cy * cy) * (ay - by)) / d
    uy = ((ax * ax + ay * ay) * (cx - bx) + (bx * bx + by * by) * (ax - cx) + (cx * cx + cy * cy) * (bx - ax)) / d
    return ux, uy


def on_arc(P, s, m_, t, c):
    ang = lambda q: math.atan2(q[1] - c[1], q[0] - c[0])
    a0, am, a1, ap = ang(s), ang(m_), ang(t), ang(P)
    ccw = lambda a, b: (b - a) % (2 * math.pi)
    sweep = ccw(a0, a1)
    if ccw(a0, am) > sweep:
        return ccw(ap, a0) <= ccw(a1, a0) + 1e-9
    return ccw(a0, ap) <= sweep + 1e-9


def draw(sm, T, ents):
    """Entities in model mm; returns [(kind, sketch geometry (m, 2D), object)] for later selection."""
    out = []
    xy = lambda p: to_sk(T, p)[:2]
    for e in ents:
        if e[0] == "L":
            a, b = xy(e[1]), xy(e[2])
            out.append(("line", (a, b), sm.CreateLine(*to_sk(T, e[1]), *to_sk(T, e[2]))))
        elif e[0] == "A":
            s, mid, t = xy(e[1]), xy(e[2]), xy(e[3])
            g = sm.Create3PointArc(*to_sk(T, e[1]), *to_sk(T, e[3]), *to_sk(T, e[2]))
            c = circle_centre(s, mid, t)
            out.append(("arc", (s, t, c, math.dist(s, c), mid), g))
        elif e[0] == "E":                       # ('E', centre, end of the major axis, end of the minor axis)
            c, a, b = (to_sk(T, q) for q in e[1:4])
            out.append(("ellipse", (c[:2], a[:2], b[:2]), sm.CreateEllipse(c[0], c[1], 0.0, a[0], a[1], 0.0, b[0], b[1], 0.0)))
        else:                                   # ('C', centre, r)
            c = to_sk(T, e[1])
            out.append(("circle", (c[:2], e[2] * MM), sm.CreateCircleByRadius(c[0], c[1], 0.0, e[2] * MM)))
    return out


DIMS = dict(ok=0, failed=[], rels=0, rels_failed=[], status=[])


def count(d, what):
    if d is None:
        DIMS["failed"].append(what)
    else:
        DIMS["ok"] += 1


class Plan:
    """Relations and dimensions of one open sketch (stl2cad's sketchplan.plan_outline, made in the plane's own
    2D frame (a, b): model (x, y) on planes parallel to the Front Plane, (x, z) on the Top Plane)."""

    def __init__(self, m, T, ents, frame, z0=0.0):
        self.m, self.T, self.ents, self.frame, self.z0 = m, T, ents, frame, z0
        self.picked = []
        x0, y0 = self.sk((0.0, 0.0)); x1, y1 = self.sk((1.0, 0.0))
        self.swapped = abs(y1 - y0) > abs(x1 - x0)

    def sk(self, ab):
        p = (ab[0], ab[1], self.z0) if self.frame == "xy" else (ab[0], 0.0, ab[1])
        return to_sk(self.T, p)[:2]

    def entity_at(self, typ, x, y, tol=1e-6):
        P = (x, y)
        if typ == "SKETCHSEGMENT":
            best = None
            for kind, geo, g in self.ents:
                if kind in ("line", "cline"):
                    (ax, ay), (bx, by) = geo
                    dx, dy = bx - ax, by - ay
                    u = max(0.0, min(1.0, ((x - ax) * dx + (y - ay) * dy) / (dx * dx + dy * dy)))
                    d = math.dist(P, (ax + u * dx, ay + u * dy)) + (0.5 * tol if kind == "cline" else 0.0)
                elif kind == "arc":
                    d = abs(math.dist(P, geo[2]) - geo[3]) + (0.0 if on_arc(P, geo[0], geo[4], geo[1], geo[2]) else 1.0)
                elif kind == "circle":
                    d = abs(math.dist(P, geo[0]) - geo[1])
                else:
                    continue
                if d < tol and (best is None or d < best[0]):
                    best = (d, g)
            return None if best is None else best[1]
        for kind, geo, g in self.ents:
            if kind not in ("line", "arc") or min(math.dist(P, geo[0]), math.dist(P, geo[1])) > tol:
                continue
            for nm in ("GetStartPoint2", "GetEndPoint2"):
                pt = call0(g, nm)
                if pt is not None and math.dist(P, (pt.X, pt.Y)) < tol and not any(pt == q for q in self.picked):
                    return pt
        for kind, geo, g in self.ents:
            if kind == "arc" and math.dist(P, geo[2]) < tol:
                pt = call0(g, "GetCenterPoint2")
                if pt is not None and not any(pt == q for q in self.picked):
                    return pt
        return None

    def select(self, picks):
        self.m.ClearSelection2(True)
        self.picked = []
        ok = True
        for k, (typ, ab) in enumerate(picks):
            if typ in ("ORIGIN", "EXTSKETCHPOINT_ORIGIN"):
                ok = ok and self.m.Extension.SelectByID2("Point1@Origin", "EXTSKETCHPOINT", 0.0, 0.0, 0.0, True, 0, NOTHING, 0)
                continue
            x, y = self.sk(ab)
            o = self.entity_at(typ, x, y)
            if o is not None and o.Select4(k > 0, NOTHING):
                self.picked.append(o)
            else:
                ok = ok and self.m.Extension.SelectByID2("", typ, x, y, 0.0, k > 0, 0, NOTHING, 0)
        return ok

    def hv(self, name):
        if not self.swapped:
            return name
        return {"sgHORIZONTAL2D": "sgVERTICAL2D", "sgVERTICAL2D": "sgHORIZONTAL2D", "H": "V", "V": "H",
                "sgHORIZONTALPOINTS2D": "sgVERTICALPOINTS2D", "sgVERTICALPOINTS2D": "sgHORIZONTALPOINTS2D"}.get(name, name)

    def run(self, ops):
        for op in ops:
            try:
                if op[0] == "rel":
                    _, rel, picks, what = op
                    if self.select(picks):
                        self.m.SketchAddConstraints(self.hv(rel)); DIMS["rels"] += 1
                    else:
                        DIMS["rels_failed"].append(what)
                elif op[0] == "dim":
                    _, kind, picks, text, what = op
                    d = None
                    if self.select(picks):
                        tx, ty = self.sk(text)
                        d = {"any": self.m.AddDimension2, "H": self.m.AddHorizontalDimension2,
                             "V": self.m.AddVerticalDimension2}[self.hv(kind)](tx, ty, 0.0)
                    count(d, what)
                elif op[0] == "centerline":
                    _, ax, ends, what = op
                    (x1, y1), (x2, y2) = self.sk(ends[0]), self.sk(ends[1])
                    g = self.m.SketchManager.CreateCenterLine(x1, y1, 0.0, x2, y2, 0.0)
                    if g is None:
                        DIMS["rels_failed"].append(what); continue
                    self.ents.append(("cline", ((x1, y1), (x2, y2)), g))
                    self.m.ClearSelection2(True)
                    if g.Select4(False, NOTHING):
                        self.m.SketchAddConstraints("sgVERTICAL2D" if abs(x2 - x1) < abs(y2 - y1) else "sgHORIZONTAL2D")
                        DIMS["rels"] += 1
                    self.m.ClearSelection2(True)
                    if self.m.Extension.SelectByID2("Point1@Origin", "EXTSKETCHPOINT", 0.0, 0.0, 0.0, False, 0, NOTHING, 0) \
                            and g.Select4(True, NOTHING):
                        self.m.SketchAddConstraints("sgATMIDDLE"); DIMS["rels"] += 1
                    self.m.ClearSelection2(True)
                    d = self.m.AddDimension2(x2 + 0.002, y2 + 0.002, 0.0) if g.Select4(False, NOTHING) else None
                    count(d, what + " length")
            except Exception as ex:
                DIMS["failed"].append(f"{op[-1]}: {type(ex).__name__}")
        self.m.ClearSelection2(True)


def circle_dims(m, ents, what):
    """Each circle: diameter, centre from the origin (horizontal and vertical)."""
    for kind, (c, r), g in [e for e in ents if e[0] == "circle"]:
        try:
            m.ClearSelection2(True)
            d = m.AddDimension2(c[0] + r + 0.003, c[1] + 0.003, 0.0) if g.Select4(False, NOTHING) else None
            count(d, f"{what} diameter")
            cp = call0(g, "GetCenterPoint2")
            for k_ in ("H", "V"):
                if abs(c[0] if k_ == "H" else c[1]) < 1e-9:
                    continue
                m.ClearSelection2(True)
                ok = cp.Select4(False, NOTHING) and m.Extension.SelectByID2("Point1@Origin", "EXTSKETCHPOINT", 0, 0, 0,
                                                                              True, 0, NOTHING, 0)
                d = (m.AddHorizontalDimension2(c[0] / 2, c[1] + 0.004, 0.0) if k_ == "H"
                     else m.AddVerticalDimension2(c[0] + 0.004, c[1] / 2, 0.0)) if ok else None
                count(d, f"{what} centre {k_}")
        except Exception as ex:
            DIMS["failed"].append(f"{what}: {type(ex).__name__}")
    m.ClearSelection2(True)


def ellipse_dims(m, ents, seg, what):
    """The ellipse's centre pierced by the arm's spline; the major-axis end from the centre (horizontal and
    vertical distances: its length and direction), the minor-axis end's distance (its length)."""
    for kind, (c, a, b), g in [e for e in ents if e[0] == "ellipse"]:
        try:
            cp, ma, mi = (call0(g, n) for n in ("GetCenterPoint2", "GetMajorPoint2", "GetMinorPoint2"))
            m.ClearSelection2(True)
            if cp.Select4(False, NOTHING) and seg.Select4(True, NOTHING):
                m.SketchAddConstraints("sgATPIERCE"); DIMS["rels"] += 1
            else:
                DIMS["rels_failed"].append(f"{what} centre on the spline")
            for k_ in ("H", "V"):
                dd = (a[0] - c[0]) if k_ == "H" else (a[1] - c[1])
                m.ClearSelection2(True)
                ok = cp.Select4(False, NOTHING) and ma.Select4(True, NOTHING)
                if abs(dd) < 1e-7:
                    if ok:
                        m.SketchAddConstraints("sgVERTICALPOINTS2D" if k_ == "H" else "sgHORIZONTALPOINTS2D"); DIMS["rels"] += 1
                    continue
                d = (m.AddHorizontalDimension2((c[0] + a[0]) / 2, (c[1] + a[1]) / 2 + 0.003, 0.0) if k_ == "H"
                     else m.AddVerticalDimension2((c[0] + a[0]) / 2 + 0.003, (c[1] + a[1]) / 2, 0.0)) if ok else None
                count(d, f"{what} major axis {k_}")
            m.ClearSelection2(True)
            ok = cp.Select4(False, NOTHING) and mi.Select4(True, NOTHING)
            d = m.AddDimension2((c[0] + b[0]) / 2 + 0.003, (c[1] + b[1]) / 2 + 0.003, 0.0) if ok else None
            count(d, f"{what} minor semi-axis")
        except Exception as ex:
            DIMS["failed"].append(f"{what}: {type(ex).__name__}")
    m.ClearSelection2(True)


def status(f):
    try:
        st = call0(call0(f, "GetSpecificFeature2"), "GetConstrainedStatus")
        s = {1: "unknown", 2: "under defined", 3: "fully defined", 4: "over defined", 5: "no solution",
             6: "invalid solution"}.get(st, str(st))
    except Exception as ex:
        s = f"not available ({type(ex).__name__})"
    DIMS["status"].append((f.Name, s))
    return s


def sketch(m, plane, ents, name, plan=None, circles=False, ellipse_seg=None):
    """Sketch of ents on plane; then its relations and dimensions: plan = (frame, z0, ops), circles: each circle
    dimensioned, ellipse_seg: the spline its ellipse's centre is pierced by."""
    sm, T, h = open_sketch(m, plane)
    E = draw(sm, T, ents)
    sm.AddToDB = False
    m.ClearSelection2(True)
    h.Select4(False, NOTHING)
    m.EditDelete()
    if DIMENSION:
        if plan is not None:
            Plan(m, T, E, plan[0], plan[1]).run(plan[2])
        if circles:
            circle_dims(m, E, name)
        if ellipse_seg is not None:
            ellipse_dims(m, E, ellipse_seg, name)
    sm.InsertSketch(True)
    f = m.FeatureByPositionReverse(0)
    f.Name = name
    if DIMENSION:
        status(f)
    return f


def plane_at_z(m, z, name):
    """Plane parallel to the Front Plane at model z (mm), side checked through a sketch transform."""
    for flip in ((256, 0) if z < 0 else (0, 256)):
        m.ClearSelection2(True)
        m.Extension.SelectByID2("Front Plane", "PLANE", 0, 0, 0, False, 0, NOTHING, 0)
        if m.FeatureManager.InsertRefPlane(8 | flip, abs(z) * MM, 0, 0, 0, 0) is None:
            continue
        f = m.FeatureByPositionReverse(0)
        sm, T, h = open_sketch(m, f)
        off = to_sk(T, (0.0, 0.0, z))[2] / MM
        sm.AddToDB = False
        sm.InsertSketch(True)
        sk = m.FeatureByPositionReverse(0)
        m.ClearSelection2(True); sk.Select2(False, 0); m.Extension.DeleteSelection2(0)
        if abs(off) < 1e-6:
            f.Name = name
            return f
        m.ClearSelection2(True); f.Select2(False, 0); m.Extension.DeleteSelection2(0)
    raise RuntimeError(f"no plane at z = {z}")


def extrude_mid(m, sk, depth, cut=False):
    m.ClearSelection2(True)
    sk.Select2(False, 0)
    fm = m.FeatureManager
    if cut:
        return fm.FeatureCut4(True, False, False, CONST["swEndCondMidPlane"], 0, depth * MM, 0.0, False, False, False,
                              False, 0.0, 0.0, False, False, False, False, False, True, True, False, False, False, 0,
                              0.0, False, False)
    return fm.FeatureExtrusion3(True, False, False, CONST["swEndCondMidPlane"], 0, depth * MM, 0.0, False, False, False,
                                False, 0.0, 0.0, False, False, False, False, True, True, True, 0, 0.0, False)


def fillet(m, edges, r):
    fm = m.FeatureManager
    d = fm.CreateDefinition(CONST["swFmFillet"])
    d.Initialize(CONST["swConstRadiusFillet"])
    d.Edges = VARIANT(pythoncom.VT_ARRAY | pythoncom.VT_DISPATCH, edges)
    d.DefaultRadius = r * MM
    return fm.CreateFeature(d)


def face_info(f):
    bx = call0(f, "GetBox")
    c = tuple((bx[k] + bx[k + 3]) / 2 / MM for k in range(3))
    try:
        pl = bool(call0(call0(f, "GetSurface"), "IsPlane"))
    except Exception:
        pl = False
    return pl, (tuple(call0(f, "Normal")) if pl else None), c


def line3d(m, p0, p1, name, attach=False):
    """3D sketch with one line; attach: its ends fixed where they are, on the corners of the two trunk sections
    (coincident relations to the section points gave invalid solutions and refused lofts)."""
    sm = m.SketchManager
    m.ClearSelection2(True)
    for attempt in range(3):
        sm.Insert3DSketch(True)
        if call0(sm, "ActiveSketch") is not None or call0(m, "GetActiveSketch2") is not None:
            break
    sm.AddToDB = True
    ln = None
    for attempt in range(4):
        ln = sm.CreateLine(*(v * MM for v in p0), *(v * MM for v in p1))
        if ln is not None:
            break
    sm.AddToDB = False
    if attach and DIMENSION and ln is not None:
        for end in ("GetStartPoint2", "GetEndPoint2"):
            m.ClearSelection2(True)
            try:
                if call0(ln, end).Select4(False, NOTHING):
                    m.SketchAddConstraints("sgFIXED"); DIMS["rels"] += 1
                else:
                    DIMS["rels_failed"].append(f"{name} end fixed")
            except Exception as ex:
                DIMS["rels_failed"].append(f"{name} end fixed: {type(ex).__name__}")
        m.ClearSelection2(True)
    sm.Insert3DSketch(True)
    f = m.FeatureByPositionReverse(0)
    f.Name = name
    if attach and DIMENSION:
        status(f)
    return f, ln


def spline3d(m, pts, name):
    """3D sketch with the natural spline through pts (a line for two); returns (feature, segment, sketch points)."""
    sm = m.SketchManager
    m.ClearSelection2(True)
    for attempt in range(3):
        sm.Insert3DSketch(True)
        if call0(sm, "ActiveSketch") is not None or call0(m, "GetActiveSketch2") is not None:
            break
    sm.AddToDB = True
    g = None
    for attempt in range(4):
        if len(pts) == 2:
            g = sm.CreateLine(*(v * MM for v in pts[0]), *(v * MM for v in pts[1]))
        else:
            g = sm.CreateSpline2(VARIANT(pythoncom.VT_ARRAY | pythoncom.VT_R8, [c * MM for p in pts for c in p]), True)
        if g is not None:
            break
    sk = call0(sm, "ActiveSketch")
    P = [(p.X / MM, p.Y / MM, p.Z / MM, p) for p in (call0(sk, "GetSketchPoints2") or [])]
    sm.AddToDB = False
    if DIMENSION:                               # the spline's points fixed where the fit put them (SolidWorks
        for x, y, z, o in P:                    # takes no z dimension in a 3D sketch; edit them by their X, Y, Z)
            m.ClearSelection2(True)
            try:
                if o.Select4(False, NOTHING):
                    m.SketchAddConstraints("sgFIXED"); DIMS["rels"] += 1
            except Exception as ex:
                DIMS["rels_failed"].append(f"{name} point fixed: {type(ex).__name__}")
        m.ClearSelection2(True)
    sm.Insert3DSketch(True)
    f = m.FeatureByPositionReverse(0)
    f.Name = name
    if DIMENSION:
        status(f)
    if g is None:
        raise RuntimeError(f"{name}: no spline")
    return f, g, P


def normal_plane(m, seg, spts, q, name):
    """Plane normal to the path through its point q (the sketch point there, else by coordinates)."""
    near = [o for x, y, z, o in spts if math.dist((x, y, z), q) < 1e-4]
    tries = []
    if near:
        tries.append(lambda: (seg.Select4(False, sd(m, 0)), near[0].Select4(True, sd(m, 1))))
    tries.append(lambda: (m.Extension.SelectByID2("", "EXTSKETCHPOINT", *(c * MM for c in q), False, 1, NOTHING, 0),
                          seg.Select4(True, sd(m, 0))))
    for sel in tries:
        m.ClearSelection2(True)
        sel()
        if m.FeatureManager.InsertRefPlane(2, 0, 4, 0, 0, 0) is not None:
            f = m.FeatureByPositionReverse(0); f.Name = name
            return f
    raise RuntimeError(f"{name}: no plane normal to the path")


def sd(m, mark):
    d = call0(m.SelectionManager, "CreateSelectData"); d.Mark = mark
    return d


def delete(m, feats):
    for f in feats:
        try:
            m.ClearSelection2(True); f.Select2(False, 0); m.Extension.DeleteSelection2(0)
        except Exception:
            pass


def loft(m, secs, guides=(), centerline=None, keep_tangency=True):
    m.ClearSelection2(True)
    for k, s in enumerate(secs):
        s.Select2(k > 0, 1)
    for g in guides:
        sd = call0(m.SelectionManager, "CreateSelectData"); sd.Mark = 2
        g.Select4(True, sd)
    if centerline is not None:
        sd = call0(m.SelectionManager, "CreateSelectData"); sd.Mark = 4
        centerline.Select4(True, sd)
    return m.FeatureManager.InsertProtrusionBlend2(False, keep_tangency, False, 1.0, 0, 0, 1.0, 1.0, True, True,
                                                   False, 0.0, 0.0, 0, True, True, True, 0)


def corners(ents):
    return [e[1] for e in ents if e[0] == "A"]


def feature_name(face):
    try:
        return call0(call0(face, "GetFeature"), "Name")
    except Exception:
        return None


def junction_edges(m):
    """{(feature, feature): [edges]} for edges between a face of an arm and a face of another arm, a trunk
    loft, the bosses or the cradle features (faces made by the cuts are not included)."""
    ok = lambda n: n is not None and n.startswith(("Arm ", "Trunk ", "Bosses", "Cradle", "Rib", "End fillet"))
    groups = {}
    for b in (m.GetBodies2(0, True) or []):
        for e in call0(b, "GetEdges") or []:
            try:
                fs = list(call0(e, "GetTwoAdjacentFaces2"))
                names = tuple(sorted({feature_name(f) for f in fs}))
            except Exception:
                continue
            if len(names) != 2 or not all(ok(n) for n in names) or not any(n.startswith("Arm ") for n in names):
                continue
            groups.setdefault(names, []).append(e)
    return groups


def junction_fillet(m):
    """One fillet R_FILLET on every junction edge; if refused, one per pair of features at R_FILLET, then at half."""
    t0 = time.time()
    groups = junction_edges(m)
    if not groups:
        print("junction fillet: no edges found"); return
    n = sum(len(g) for g in groups.values())
    if n > FILLET_MAX_EDGES:
        print(f"junction fillet: skipped, {n} edges in {len(groups)} pairs of features (more than {FILLET_MAX_EDGES})")
        return
    print(f"junction fillet: {len(groups)} pairs of features, {n} edges; trying them in one feature", flush=True)
    f = fillet(m, [e for g in groups.values() for e in g], R_FILLET)
    if f is not None:
        f.Name = "Junction fillet"
        print(f"junction fillet: R{R_FILLET:g} on {sum(len(g) for g in groups.values())} edges of {len(groups)} pairs "
              f"of features in one feature; {time.time() - t0:.0f} s")
        return
    todo, k, done = sorted(groups), 0, {}
    for r in (R_FILLET, 0.5 * R_FILLET):
        left = []
        for pair in todo:
            if time.time() - t0 > FILLET_TIME:
                left.append(pair); continue
            g = junction_edges(m).get(pair)
            if not g:
                continue
            f = fillet(m, g, r)
            print(f"  {' / '.join(pair)} at R{r:g}: {'made' if f is not None else 'refused'}; "
                  f"{time.time() - t0:.0f} s", flush=True)
            if f is None:
                left.append(pair); continue
            k += 1; f.Name = f"Junction fillet {k}"; done[r] = done.get(r, 0) + 1
        todo = left
    print(f"junction fillet: {len(groups)} pairs; " + ", ".join(f"{n} at R{r:g}" for r, n in done.items())
          + (f"; not filleted: {'; '.join(' / '.join(p) for p in todo)}" if todo else "") + f"; {time.time() - t0:.0f} s")


# ---------------------------------------------------------------------------------------------------------------
def build():
    t0 = time.time()
    m = new_part()
    made = []
    # bosses
    pl = plane_at_z(m, H_BOSS / 2, "Boss plane")
    sk = sketch(m, pl, [("C", (x, y, H_BOSS / 2), R_BOSS) for x, y in BOSSES], "Boss sketch", circles=True)
    f = extrude_mid(m, sk, H_BOSS)
    if f is not None: f.Name = "Bosses"
    made.append(check(m, "Bosses", f))
    # cradle
    path = sketch(m, "Top Plane", PATH, "Cradle path", plan=PLANS["path"])
    prof = sketch(m, plane_at_z(m, Z_LEG, "Cradle end plane"), PROFILE, "Cradle section", plan=PLANS["profile"])
    m.ClearSelection2(True); prof.Select2(False, 1); path.Select2(True, 4)
    f = m.FeatureManager.CreateFeature(m.FeatureManager.CreateDefinition(CONST["swFmSweep"]))
    if f is not None: f.Name = "Cradle"
    made.append(check(m, "Cradle", f))
    rib = sketch(m, "Top Plane", RIB, "Rib outline", plan=PLANS["rib"])
    f = extrude_mid(m, rib, 2 * RIB_W)
    if f is not None: f.Name = "Rib"
    made.append(check(m, "Rib", f))
    es = []
    for p in RIB_PTS:
        m.ClearSelection2(True)
        if m.Extension.SelectByID2("", "EDGE", p[0] * MM, p[1] * MM, p[2] * MM, False, 0, NOTHING, 0):
            es.append(m.SelectionManager.GetSelectedObject6(1, -1))
    m.ClearSelection2(True)
    f = fillet(m, es, RIB_F) if len(es) == len(RIB_PTS) else None
    if f is not None: f.Name = "Rib fillet"
    made.append(check(m, "Rib fillet", f))
    es = []
    for b in (m.GetBodies2(0, True) or []):
        for fc in call0(b, "GetFaces") or []:
            pl_, n, c = face_info(fc)
            if pl_ and abs(abs(n[2]) - 1) < 1e-6 and min(abs(c[2] - z) for z in END_Z) < 1e-3:
                es += list(call0(fc, "GetEdges") or [])
    f = fillet(m, es, END_R) if es else None
    if f is not None: f.Name = "End fillet"
    made.append(check(m, "End fillet", f))
    print(f"  time so far {time.time() - t0:.0f} s")
    # trunk
    secs = []
    for k, (z, ents) in enumerate(SECS):
        secs.append(sketch(m, plane_at_z(m, z, f"Trunk plane {k + 1}"), ents, f"Trunk section {k + 1}",
                           plan=PLANS[f"section {k + 1}"]))
    for k in range(len(SECS) - 1):
        name = f"Trunk {k + 1}"
        c0, c1 = corners(SECS[k][1]), corners(SECS[k + 1][1])
        ok = False
        for variant in ("one guide", "all guides", "no guides"):
            pairs = [(c0[0], c1[0])] if variant == "one guide" else (list(zip(c0, c1)) if variant == "all guides" else [])
            gs = [line3d(m, a, b, f"{name} guide {i + 1}", attach=True)[0] for i, (a, b) in enumerate(pairs)]
            f = loft(m, [secs[k], secs[k + 1]], gs)
            ok = check(m, name, f, quiet=True)
            if ok:
                f.Name = name
                print(f"  ({variant})")
                break
            if f is not None:
                delete(m, [f])
            delete(m, gs)
        if not ok:
            print(f"{name}: no loft agreed with CadQuery; made without guides")
            f = loft(m, [secs[k], secs[k + 1]], (), keep_tangency=False)
            if f is not None: f.Name = name     # the junction fillet finds the trunk by its name
            check(m, name, f)
        made.append(ok)
    print(f"  time so far {time.time() - t0:.0f} s")
    # arms
    for n, arm in enumerate(ARMS):
        name = f"Arm {n + 1}"
        path, seg, spts = spline3d(m, arm["points"], f"{name} path")
        cs = []
        for k, (i, c, pa, pb) in enumerate(arm["sec"]):
            pl = normal_plane(m, seg, spts, arm["points"][i], f"{name} plane {k + 1}")
            cs.append(sketch(m, pl, [("E", c, pa, pb)], f"{name} section {k + 1}", ellipse_seg=seg))
        ok = False
        for variant in ("spline as centerline", "no centerline", "ruled pairs"):
            if variant == "ruled pairs":        # as the CadQuery reference: a loft between each pair of sections
                fs = [loft(m, cs[k:k + 2]) for k in range(len(cs) - 1)]
                f = fs[-1] if all(x is not None for x in fs) else None
            else:
                fs = [loft(m, cs, centerline=seg if variant == "spline as centerline" else None)]
                f = fs[0]
            ok = check(m, name, f, quiet=True, tol=TOL_ARM)
            if ok:
                for k, x in enumerate(fs):
                    x.Name = name if len(fs) == 1 else f"{name}.{k + 1}"
                print(f"  ({variant})")
                break
            delete(m, [x for x in fs if x is not None])
        if not ok:
            print(f"{name}: no variant agreed with CadQuery; made with the spline as centerline")
            f = loft(m, cs, centerline=seg)
            if f is not None: f.Name = name     # the junction fillet finds the arm by its name
            check(m, name, f, tol=TOL_ARM)
        made.append(ok)
    print(f"  time so far {time.time() - t0:.0f} s")
    # cuts
    sk = sketch(m, plane_at_z(m, H_BOSS + 25.0, "Top cut plane"), [("L", (a[0], a[1], H_BOSS + 25.0), (b[0], b[1], H_BOSS + 25.0))
                for a, b in zip(TOP_BOX, TOP_BOX[1:] + TOP_BOX[:1])], "Top cut sketch", plan=PLANS["top box"])
    f = extrude_mid(m, sk, 50.0, cut=True)
    if f is not None: f.Name = "Top cut"
    made.append(check(m, "Top cut", f))
    sk = sketch(m, "Top Plane", TYRE, "Tyre space", plan=PLANS["tyre"])
    f = extrude_mid(m, sk, 80.0, cut=True)
    if f is not None: f.Name = "Tyre cut"
    made.append(check(m, "Tyre cut", f))
    sk = sketch(m, "Front Plane", [("C", (x, y, 0.0), R_HOLE) for x, y in BOSSES], "Hole sketch", circles=True)
    f = extrude_mid(m, sk, 60.0, cut=True)
    if f is not None: f.Name = "Holes"
    made.append(check(m, "Holes", f))
    v, c = mass(m)
    print(f"before the fillets: volume {v:.3f} mm^3 (CadQuery {FINAL[0]:.3f}), centre {math.dist(c, FINAL[1]):.4f} mm "
          f"off; {sum(made)} of {len(made)} features agree; {time.time() - t0:.0f} s")
    if R_FILLET > 0:
        junction_fillet(m)
    v1, c1 = mass(m)
    print(f"final: volume {v1:.3f} mm^3 ({v1 - v:+.3f} from the fillets), bodies {len(m.GetBodies2(0, True) or [])}; "
          f"{time.time() - t0:.0f} s")
    if DIMENSION:
        st = [s for _, s in DIMS["status"]]
        print(f"dimensions: {DIMS['ok']} added" + (f", {len(DIMS['failed'])} failed: {DIMS['failed'][:20]}" if DIMS['failed'] else ""))
        print(f"relations: {DIMS['rels']} added" + (f", {len(DIMS['rels_failed'])} failed: {DIMS['rels_failed'][:20]}" if DIMS['rels_failed'] else ""))
        print("sketch status: " + ", ".join(f"{k} x {st.count(k)}" for k in sorted(set(st))))
        bad = [n for n, s in DIMS["status"] if s != "fully defined"]
        if bad:
            print("not fully defined: " + "; ".join(bad))
    hide_construction(m)
    return m


def hide_construction(m):
    """Hide the planes and sketches the script made (hidden, not suppressed: the features depend on them)."""
    keep = ("Front Plane", "Top Plane", "Right Plane")
    planes = sketches = 0
    feats, f = [], m.FirstFeature()
    while f is not None:
        feats.append(f)
        sub = f.GetFirstSubFeature()
        while sub is not None:
            feats.append(sub); sub = sub.GetNextSubFeature()
        f = f.GetNextFeature()
    for f in feats:
        try:
            t = f.GetTypeName2()
            if t == "RefPlane" and f.Name not in keep:
                m.ClearSelection2(True); f.Select2(False, 0); m.BlankRefGeom(); planes += 1
            elif t in ("ProfileFeature", "3DProfileFeature"):
                m.ClearSelection2(True); f.Select2(False, 0); m.BlankSketch(); sketches += 1
        except Exception:
            pass
    m.ClearSelection2(True)
    m.GraphicsRedraw2()
    print(f"hidden: {planes} planes, {sketches} sketches")


if __name__ == "__main__":
    try:
        m = build()
        if len(sys.argv) > 1:
            m.SaveAs3(sys.argv[1], 0, 0)
    except Exception:
        traceback.print_exc()
